# Text run by a shell interpreter or evaluator (stdin, here-document,
# here-string, substitution, argument string), plain and wrapped.
P = 'git commit -m "{M}"'
for sh in ("bash", "sh", "zsh", "dash"):
    CORPUS1["sh-pipe-echo+" + sh] = "echo '%s' | %s" % (P, sh)
    CORPUS1["sh-pipe-printf+" + sh] = "printf '%%s\\n' '%s' | %s" % (P, sh)
    CORPUS1["sh-cat-hd+" + sh] = "cat <<'EOF' | %s\n%s\nEOF" % (sh, P)
    CORPUS1["sh-hd+" + sh] = "%s <<'EOF'\n%s\nEOF" % (sh, P)
    CORPUS1["sh-hd-unquoted+" + sh] = "%s <<EOF\n%s\nEOF" % (sh, P)
    CORPUS1["sh-herestring+" + sh] = "%s <<< '%s'" % (sh, P)
    CORPUS1["sh-procsub+" + sh] = "%s <(echo '%s')" % (sh, P)
    CORPUS1["sh-xargs+" + sh] = "echo '%s' | xargs -I{} %s -c '{}'" % (P, sh)
for w in ("env", "nohup", "time", "nice"):
    CORPUS1["sh-pipe-wrapped+" + w] = "echo '%s' | %s bash" % (P, w)
    CORPUS1["sh-hd-wrapped+" + w] = "%s bash <<'EOF'\n%s\nEOF" % (w, P)
    CORPUS1["sh-herestring-wrapped+" + w] = "%s bash <<< '%s'" % (w, P)
CORPUS1["sh-ssh-pipe"] = "ssh host \"echo 'git commit -m \\\"{M}\\\"' | bash\""
CORPUS1["sh-ssh-hd"] = "ssh host bash <<'EOF'\n%s\nEOF" % P
CORPUS1["eval-subst"] = "eval \"$(echo '%s')\"" % P
CORPUS1["eval-dq"] = "eval \"git commit -m '{M}'\""
CORPUS1["eval-sq"] = "eval '%s'" % P
CORPUS1["source-stdin"] = "echo '%s' | source /dev/stdin" % P
CORPUS1["dot-stdin"] = "echo '%s' | . /dev/stdin" % P
CORPUS1["source-procsub"] = "source <(echo '%s')" % P
for bk, b in BASES.items():
    for pk, p in PREFIXES.items():
        CORPUS1["%s+%s" % (pk, bk)] = p + b
    for wk, (pre, post) in WRAPS.items():
        CORPUS1["%s+%s" % (wk, bk)] = pre + b + post

