def clean2(cmd):
    """The clean run of a CORPUS2 spelling: clean.txt for credit.txt and a
    neutral text for each spelled-out credit."""
    for a, b in (("credit.txt", "clean.txt"), ("cred*.txt", "clean.txt"),
                 ("Co-authored-by: Claude <c@x>", "Reviewed-by: Bob <b@x>"),
                 ("Claude <noreply@anthropic.com>", "Bob <b@x>"),
                 ("Generated\\ with\\ Claude\\ Code", "fix\\ it"),
                 ('Generated with Cl""aude Code', "fix it"),
                 ("Generated with Cl'\"aude Code\"", "fix it"), ("Cl'", "fix'")):
        cmd = cmd.replace(a, b)
    return cmd


